const projectIdentity=p=>String(p.project_id||p.local_id||p.title||'unnamed');
let libraryFetching=false;
const libraryBox=document.createElement('div');libraryBox.style.cssText='margin:16px 10px';libraryBox.innerHTML='<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px"><span style="font-size:12px;color:#a9b7ca">我的项目</span><button id="libraryProjectTrash" class="text" style="font-size:11px">回收站</button></div><div id="projectLibraryList" aria-label="项目列表" style="display:grid;gap:8px"></div><p id="projectLibraryStatus" class="subtle" style="font-size:11px">所有项目独立保存到本机</p>';document.querySelector('.project-mini').before(libraryBox);
async function refreshProjectLibrary(){if(libraryFetching)return;libraryFetching=true;try{const list=await(await fetch('/api/projects')).json(),box=document.querySelector('#projectLibraryList'),id=projectIdentity(data);if(!list.some(p=>p.identity===id)&&!data.deleted)list.unshift({identity:id,title:data.title,pending:true,characters:data.characters?.length||0,shots:data.shots?.length||0});const html=list.map(p=>'<div style="display:flex;align-items:center;gap:6px"><button data-library-project="'+esc(p.identity)+'" aria-pressed="'+(p.identity===id)+'" style="text-align:left;flex:1;min-width:0;padding:12px;border-radius:10px;border:1px solid '+(p.identity===id?'#507567':'#2d3b4c')+';background:'+(p.identity===id?'#20392f':'#151f2c')+';color:'+(p.identity===id?'#c5f0df':'#d6e2ef')+'"><b style="display:block;font-size:13px">'+esc(p.title)+'</b><small style="display:block;color:#a7b8ca;margin-top:5px">'+(p.pending?'待保存':p.characters+' 位角色 · '+p.shots+' 个分镜')+'</small></button><button data-delete-library-project="'+esc(p.identity)+'" title="删除项目 '+esc(p.title)+'" aria-label="删除项目 '+esc(p.title)+'" style="flex:none;color:#f1b6b6;padding:8px 6px;font-size:11px">删除</button></div>').join('');if(box.innerHTML!==html){box.innerHTML=html;box.querySelectorAll('[data-library-project]').forEach(b=>b.onclick=()=>openLocalProject(b.dataset.libraryProject));box.querySelectorAll('[data-delete-library-project]').forEach(b=>b.onclick=()=>askDeleteLibraryProject(list.find(p=>p.identity===b.dataset.deleteLibraryProject)));}document.querySelector('#projectLibraryStatus').textContent=list.length+' 个项目 · 导入新项目会新增一项';}catch{}finally{libraryFetching=false}}
async function openLocalProject(id){if(id===projectIdentity(data))return;try{await flushDisk();if(diskConflict||diskBusy)throw Error('当前修改尚未保存，请先备份或稍后再打开其他项目');const r=await fetch('/api/project?id='+encodeURIComponent(id)),result=await r.json();if(!result.project||result.project.deleted)throw Error('项目不存在或已移入回收站');data=result.project;diskRevision=result.revision;diskIdentity=projectIdentity(data);lastDiskData=JSON.stringify(data);diskConflict=false;ci=si=tab=0;browserSave();document.querySelector('#diskSaveWarning')?.remove();render();await refreshProjectLibrary();toast('已打开 '+data.title)}catch(error){toast(error.message)}}
document.querySelector('#libraryProjectTrash').onclick=showProjectTrash;
const renderBeforeProjectLibrary=render;render=function(){renderBeforeProjectLibrary();void refreshProjectLibrary()};setInterval(refreshProjectLibrary,5000);refreshProjectLibrary();
// The project list already identifies the open project; omit duplicate summaries.
document.querySelectorAll('aside .aside-label').forEach(label=>{if(label.textContent.trim()==='当前项目')label.hidden=true});
document.querySelector('.project-mini').style.display='none';
const overviewProjectLabel=document.querySelector('.overview-head .pill');if(overviewProjectLabel)overviewProjectLabel.hidden=true;